const rs=await Promise.all([
 tools.exec_command({cmd:"\"$HORIZON_GIT\" status --short --untracked-files=all -- FormalizedSources/Curves/Hartshorne | head -30",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:3000}),
 tools.exec_command({cmd:"\"$HORIZON_BIN\" roadmap list --focus Hartshorne --max-depth 1 --json | head -c 6000",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:4000}),
 tools.exec_command({cmd:"\"$HORIZON_BIN\" ps --json | jq '[.sessions[]? // .runs[]?] | map(select((.project // \"\") == \"Hartshorne\"))'",workdir:"/home/axel/LeanAlgebraicGeometry-Horizon",yield_time_ms:10000,max_output_tokens:3000})
]); rs.forEach(r=>text(r.output));

const results = await Promise.all([
  tools.exec_command({cmd:"$HORIZON_BIN graph -p Hartshorne sync","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon","yield_time_ms":1000,"max_output_tokens":8000}),
  tools.exec_command({cmd:"$HORIZON_GIT diff d36a818c80^ d36a818c80 --numstat; $HORIZON_GIT show -s --format='%P%n%T%n%(trailers)' d36a818c80","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon","yield_time_ms":10000,"max_output_tokens":3000}),
  tools.exec_command({cmd:"rg -l 'mulEquivDivisorSheaf|divisorVal_mulEquiv|divisorMulPresheafIso' hgraph | head -30","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon/FormalizedSources/Curves/Hartshorne","yield_time_ms":10000,"max_output_tokens":5000}),
  tools.exec_command({cmd:"sed -n '1,180p' README.md; sed -n '1,120p' PROVENANCE.md","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon/FormalizedSources/Curves/Hartshorne","yield_time_ms":10000,"max_output_tokens":8000})
]);
for (const r of results) text(JSON.stringify({session_id:r.session_id,exit_code:r.exit_code,output:r.output}));

const results = await Promise.all([
  tools.exec_command({cmd:"$HORIZON_BIN check --lean HartshorneLib.lean","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon/FormalizedSources/Curves/Hartshorne","yield_time_ms":1000,"max_output_tokens":10000}),
  tools.exec_command({cmd:"rg -l 'Hartshorne.*mulEquivDivisorSheaf|mulEquivDivisorSheaf|divisorMulPresheafApp_bijective|divisorVal_mulEquiv' hgraph/nodes | head -30 | xargs -r -n1 sh -c 'echo ===$0; sed -n \"1,70p\" \"$0\"'","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon/FormalizedSources/Curves/Hartshorne","yield_time_ms":10000,"max_output_tokens":12000}),
  tools.exec_command({cmd:"$HORIZON_GIT status --short -- FormalizedSources/Curves/Hartshorne; $HORIZON_GIT ls-tree --name-only HEAD -- FormalizedSources/Curves/Hartshorne/HartshorneLib/Chapter4DivisorSheafMul.lean; $HORIZON_GIT show HEAD:FormalizedSources/Curves/Hartshorne/HartshorneLib/Chapter4DivisorSheafMul.lean | sha256sum; sha256sum HartshorneLib/Chapter4DivisorSheafMul.lean","workdir":"/home/axel/LeanAlgebraicGeometry-Horizon","yield_time_ms":10000,"max_output_tokens":5000})
]);
for (const r of results) text(JSON.stringify({session_id:r.session_id,exit_code:r.exit_code,output:r.output}));
